FROM M_Product pr JOIN M_Product_Category_Acct ca ON ca.M_Product_Category_ID=pr.M_Product_Category_ID WHERE pr.AD_Client_ID=11 AND pr.Value='PWD-10.6' AND NOT EXISTS (SELECT 1 FROM M_Product_Acct x WHERE x.M_Product_ID=pr.M_Product_ID AND x.C_AcctSchema_ID=ca.C_AcctSchema_ID);
INSERT INTO M_ProductPrice (M_ProductPrice_ID,M_PriceList_Version_ID,M_Product_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,PriceList,PriceStd,PriceLimit,M_ProductPrice_UU)
SELECT nextidfunc((SELECT AD_Sequence_ID::int FROM AD_Sequence WHERE Name='M_ProductPrice' AND IsTableID='Y'),'N'),v.M_PriceList_Version_ID,pr.M_Product_ID,11,0,'Y',TO_TIMESTAMP('2026-11-14 15:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-14 15:00:00','YYYY-MM-DD HH24:MI:SS'),100,1.0750,1.0750,1.0750,md5('capex-td-products:price:'||pr.Value)::uuid
FROM M_Product pr, M_PriceList_Version v WHERE pr.AD_Client_ID=11 AND pr.Value='PWD-10.6' AND v.M_PriceList_Version_ID=(SELECT v2.M_PriceList_Version_ID FROM M_PriceList_Version v2 JOIN M_PriceList l ON l.M_PriceList_ID=v2.M_PriceList_ID WHERE v2.AD_Client_ID=11 AND l.Name='Purchase' AND l.IsSOPriceList='N' ORDER BY v2.ValidFrom DESC LIMIT 1)
AND NOT EXISTS (SELECT 1 FROM M_ProductPrice x WHERE x.M_PriceList_Version_ID=v.M_PriceList_Version_ID AND x.M_Product_ID=pr.M_Product_ID);
INSERT INTO M_Cost (AD_Client_ID,AD_Org_ID,M_Product_ID,M_CostType_ID,C_AcctSchema_ID,M_CostElement_ID,M_AttributeSetInstance_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,CurrentCostPrice,CurrentQty,CumulatedAmt,CumulatedQty,FutureCostPrice,Percent,CurrentCostPriceLL,FutureCostPriceLL,IsCostFrozen,M_Cost_UU)
SELECT 11,0,pr.M_Product_ID,s.M_CostType_ID,s.C_AcctSchema_ID,ce.M_CostElement_ID,0,'Y',TO_TIMESTAMP('2026-11-14 15:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-14 15:00:00','YYYY-MM-DD HH24:MI:SS'),100,1.0750,0,0,0,0,0,0,0,'N',md5('capex-td-products:cost:'||pr.Value||':'||s.C_AcctSchema_ID)::uuid
FROM M_Product pr JOIN C_AcctSchema s ON s.AD_Client_ID=11 JOIN M_CostElement ce ON ce.AD_Client_ID=11 AND ce.CostElementType='M' AND ce.CostingMethod='S'
WHERE pr.AD_Client_ID=11 AND pr.Value='PWD-10.6' AND s.C_Currency_ID=(SELECT l.C_Currency_ID FROM M_PriceList_Version v2 JOIN M_PriceList l ON l.M_PriceList_ID=v2.M_PriceList_ID WHERE v2.AD_Client_ID=11 AND l.Name='Purchase' AND l.IsSOPriceList='N' ORDER BY v2.ValidFrom DESC LIMIT 1)
AND NOT EXISTS (SELECT 1 FROM M_Cost x WHERE x.AD_Client_ID=11 AND x.AD_Org_ID=0 AND x.M_Product_ID=pr.M_Product_ID AND x.M_CostType_ID=s.M_CostType_ID AND x.C_AcctSchema_ID=s.C_AcctSchema_ID AND x.M_CostElement_ID=ce.M_CostElement_ID AND x.M_AttributeSetInstance_ID=0);

